window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"yzBZyEw5LMY","speaker":"Valdrack Ludwing Jaentschke Whitaker","role":"Foreign Minister","country":"Nicaragua","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=yzBZyEw5LMY","date":"20260926","title":"🇳🇮 Nicaragua - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":224,"words":448,"counts":{"claims":5,"promises":0,"attacks":0},"topics":[{"topic":"Cuba Russia China","share":0.3329,"seconds":74},{"topic":"drug trafficking","share":0.308,"seconds":69},{"topic":"sustainable development","share":0.2765,"seconds":62},{"topic":"Ceremony","share":0.0827,"seconds":18}],"timeline":[[2,93,null],[93,162,"drug trafficking"],[165,226,"sustainable development"],[229,303,"Cuba Russia China"],[304,323,"Ceremony"]],"stances":{"drug trafficking":"The speaker identifies drug trafficking and organized crime as major crimes linked to terrorism that threaten societies.","sustainable development":"The speaker expresses a commitment to addressing global challenges and highlights the efforts of BRICS countries in striving for better living conditions.","Cuba Russia China":"The speaker expresses unwavering solidarity with Cuba, affirms the one-China principle, and shares the struggle against fascism with the Russian Federation.","Ceremony":"The speaker concludes their address by expressing gratitude and emphasizing the goal of dignity and shared responsibility."},"claims":[{"t":154,"quote":"we see major crimes linked to drug trafficking and organized crime, which are forms of terrorism, which assail us and make us sick.","topic":"drug trafficking","kind":"fact"},{"t":209,"quote":"And we wish to stress the BRICS countries, for instance, have in striving for better living conditions for their people","topic":"sustainable development","kind":"fact"},{"t":262,"quote":"we wish to express our unwavering solidarity with the heroic people of Cuba.","topic":"Cuba Russia China","kind":"fact"},{"t":275,"quote":"the one-China principle, which is non-negotiable.","topic":"Cuba Russia China","kind":"fact"},{"t":281,"quote":"We also fully share the struggle against fascism and the right to peace waged by the Russian Federation.","topic":"Cuba Russia China","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"I now invite the Foreign Minister His Excellency Mr. Valdrac Ludwing Fonseca, Foreign Minister of Nicaragua to take the &gt;&gt; Señor Presidente. Nicaragua is addressing the 81st session of the United Nations General Assembly with the strength of the peace that we think is possible in our country and throughout the world where the human family opt for the urgent need to live in in all possible ways. This is critical to address poverty and to live in dignity, freedom, and fraternity. We bring to this forum of all peoples and states of the world the legitimate of families from the entire world and in particular in Nicaragua to live peacefully and safely, to strengthen the work that will allow all of all of us to establish better societies, to defeat extreme poverty, to live in harmony and in complementarity which are so critical to allow all societies"},{"t":93,"topic":"drug trafficking","text":"to progress and so that also we can care for and increase our resources and natural riches which will be of benefit to everyone. The conflicts assailing the world are, as we know, the enemy of the well-being to which we are all entitled. In the words of uh Ruben Dario, we are in favor of peace, peace, peace. To make headway on the goals laid out and in particular by this organization which gathers us together, we need to defeat extreme poverty. And we also need to achieve well-being for all to bring about a better world, which is so urgent a task. The scourges of our time uh are the greatest threat and greatest danger to our societies because they deprive us of our heritage. And we see major crimes linked to drug trafficking and organized crime, which are forms of terrorism, which assail us and make us sick."},{"t":165,"topic":"sustainable development","text":"Against this intimidating backdrop, our purpose, our vote, our commitment has been and remains clear. And we aspire to with more peoples around the urgent need to curb these afflictions and to bring about safety and to provide education, food, health, peace, and development for We would like warmly to greet all delegations who are present here. And we hope that you will join our commitment to address these challenges and to alleviate the suffering that we have There are many proposals that we have mentioned. And we wish to stress the BRICS countries, for instance, have in striving for better living conditions for their people and the right of all to achieve sustainable development in a complementary way."},{"t":229,"topic":"Cuba Russia China","text":"We would like to recognize and pay tribute to all brothers and sisters throughout the world who believe in ideals, principles, and values that are valuable to us all as humanity. To continue moving towards achieving the most important significant battle, which is to achieve peace so that we can defeat poverty once and for all. It is in this battle that we all have to wage to achieve peace. In this context, we wish to express our unwavering solidarity with the heroic people of Cuba. And we also recognize the principles and values expressed by the people and government of the People's Republic of In particular, the one-China principle, which is non-negotiable. We also fully share the struggle against fascism and the right to peace waged by the Russian Federation. Distinguished delegates, I wish to express to you all in this the commitment for us all to live together in a fraternal and solidarity-based way."},{"t":304,"topic":"Ceremony","text":"To achieve dignity and shared responsibility for all. Thank you very much. &gt;&gt; I thank the Foreign Minister of Nicaragua for his address."}],"compare":[{"topic":"Cuba","share":0.3629,"mean":0.0095,"rank":1,"others":23},{"topic":"Transnational Crime","share":0.3357,"mean":0.0019,"rank":1,"others":4},{"topic":"Sustainable Development","share":0.3014,"mean":0.011,"rank":1,"others":28}]};
